namespace ghidra.app.util.viewer.field;

using ghidra.app.nav;
using ghidra.framework.plugintool;
using ghidra.program.util;
using ghidra.util;



/**
 * A handler to process {@link ErrorListingField} clicks.
 */
public class ErrorFieldMouseHandler : FieldMouseHandlerExtension {

	private static Class<object>[] SUPPORTED_CLASSES = new Class[] { typeof(ErrorListingField) };

	/* @Override */
	public bool fieldElementClicked(object clickedObject, Navigatable sourceNavigatable,
			ProgramLocation location, MouseEvent mouseEvent, ServiceProvider serviceProvider) {

		if (mouseEvent.getClickCount() != 2 || mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return false;
		}
		ErrorListingField errorField = (ErrorListingField) clickedObject;
		string fieldName = errorField.getFieldFactory().getFieldName();
		Msg.showError(this, null, "Listing Field Exception", "Exception occurred while rendering '" +
			fieldName + "' field", errorField.getThrowable());
		return true;
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}

}
